const nav = [['overview','Overview','grid'],['pos','Checkout','bag'],['sales','Sales','receipt'],['inventory','Inventory','box'],['contacts','Contacts','people'],['expenses','Expenses','wallet'],['team','Team & access','shield'],['settings','Settings','settings'],['activity','Activity','clock'],['kit','UI kitchen sink','layers']];
